import{_ as i,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"CDS Hammer (Day 1) - Towards Ceph Cold Storage","description":"","frontmatter":{"title":"CDS Hammer (Day 1) - Towards Ceph Cold Storage","date":"2014-10-29T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["[Ceph]","[冷存储]","[分布式存储]","[CRUSH算法]","[数据持久性]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_1_-_Towards_Ceph_Cold_Storage.md","filePath":"posts/2014/CDS_Hammer_Day_1_-_Towards_Ceph_Cold_Storage.md","lastUpdated":1780459816000}'),a={name:"posts/2014/CDS_Hammer_Day_1_-_Towards_Ceph_Cold_Storage.md"};function s(e,l,p,n,_,g){return t(),o("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： 探讨将 Ceph 应用于冷存储的可行性和实施方案</p><p><strong>参会人员</strong>： Matthias Gravenka（美因茨大学）、Marcelo（前帕拉多大学）、Ceph 社区成员</p><p><strong>会议内容</strong>：</p><p><strong>一、背景</strong></p><p>Matthias 和 Marcelo 提出了将 Ceph 应用于冷存储的蓝图，并希望通过本次会议讨论其可行性及实施方案。</p><p><strong>二、主要议题</strong></p><ol><li><p><strong>冷存储需求</strong>：</p><ul><li>能量感知的放置策略</li><li>数据迁移最小化</li><li>数据持久性</li><li>可扩展性</li></ul></li><li><p><strong>方案探讨</strong>：</p><ul><li><strong>能量感知的放置策略</strong>： <ul><li>通过桶类型实现，了解 OSD 的电源状态，并根据时间进行动态切换。</li><li>在 OSD 映射层实现，而非 CRUSH 层。</li></ul></li><li><strong>数据迁移最小化</strong>： <ul><li>在 CRUSH 规则中添加插件功能，实现更灵活的映射方案。</li><li>标记对象属性，实现冷数据、热数据的分层存储。</li><li>引入对象重定向功能，将冷数据指向外部存储。</li></ul></li><li><strong>数据持久性</strong>： <ul><li>引入归档守护进程，实现冷数据的生命周期管理。</li></ul></li><li><strong>可扩展性</strong>： <ul><li>通过时间切片等方法，实现数据的分层存储。</li></ul></li></ul></li></ol><p><strong>三、讨论结果</strong></p><ol><li><p><strong>能量感知的放置策略</strong>：</p><ul><li>该方案可行，但需要考虑 CRUSH 映射表更新的开销。</li><li>可以通过在 OSD 映射层实现，避免修改 CRUSH 算法。</li></ul></li><li><p><strong>数据迁移最小化</strong>：</p><ul><li>可以通过 CRUSH 规则中的插件功能实现更灵活的映射方案。</li><li>可以标记对象属性，实现冷数据、热数据的分层存储。</li><li>对象重定向功能尚未实现，但已有原型。</li></ul></li><li><p><strong>数据持久性</strong>：</p><ul><li>归档守护进程的实现需要结合对象重定向功能。</li></ul></li><li><p><strong>可扩展性</strong>：</p><ul><li>通过时间切片等方法，实现数据的分层存储。</li></ul></li></ol><p><strong>四、后续行动计划</strong></p><ol><li>Matthias 和 Marcelo 将继续完善其蓝图，并撰写论文和硕士论文。</li><li>Ceph 社区成员将继续讨论并评估该方案的可行性。</li><li>一旦方案得到认可，将着手进行代码开发。</li></ol><p><strong>五、关键术语</strong></p><ul><li>冷存储</li><li>冷数据</li><li>热数据</li><li>CRUSH 算法</li><li>OSD 映射</li><li>对象重定向</li><li>归档守护进程</li></ul>',14)])])}const u=i(a,[["render",s]]);export{C as __pageData,u as default};
